  -- [18/94] group 2 (DevOps/Infrastructure): DevOps Engineer - Vận Hành ERP Odoo, FastApi
  jid := '280f2207-262f-50f2-839d-794932adca8c'::uuid;
  cid := company_ids[6];
  insert into public.job_posts (
