  -- [68/94] group 10 (Networking): Network Engineer
  jid := 'de32fa48-5608-50ca-b58b-64bd4723d1c4'::uuid;
  cid := company_ids[8];
  insert into public.job_posts (
    id, company_id, created_by_user_id, title, description, requirements,
